     1	package br.com.mareal.plans;
     2	
     3	import br.com.mareal.domain.ApiException;
     4	import br.com.mareal.domain.Money;
     5	import br.com.mareal.domain.RoomType;
     6	import java.math.BigDecimal;
     7	import java.time.DayOfWeek;
     8	import java.util.Map;
     9	
    10	public class WeekendPackagePlan implements RatePlan {
    11	    private static final Map<RoomType, BigDecimal> PRICE_BY_TYPE = Map.of(
    12	            RoomType.STANDARD, Money.of("520.00"),
    13	            RoomType.DELUXE, Money.of("820.00"),
    14	            RoomType.SUITE, Money.of("1200.00"));
    15	    private static final BigDecimal REFUND_SHARE = new BigDecimal("0.5");
    16	
    17	    public String code() {
    18	        return "WEEKEND_PACKAGE";
    19	    }
    20	
    21	    public Pricing price(Stay stay) {
    22	        boolean fridayToSunday = stay.checkIn().getDayOfWeek() == DayOfWeek.FRIDAY && stay.nights() == 2;
    23	        if (!fridayToSunday) {
    24	            throw ApiException.invalid("O WEEKEND_PACKAGE só vale com entrada na sexta e saída no domingo seguinte.");
    25	        }
    26	        return Pricing.noDiscount(PRICE_BY_TYPE.get(stay.roomType()));
    27	    }
    28	
    29	    public BigDecimal refund(BigDecimal amountPaid) {
    30	        return Money.percent(amountPaid, REFUND_SHARE);
    31	    }
    32	}

