     1	package br.com.mareal.domain;
     2	
     3	import br.com.mareal.plans.RatePlan;
     4	import java.math.BigDecimal;
     5	import java.time.LocalDate;
     6	
     7	public class Reservation {
     8	    public final int id;
     9	    public final Room room;
    10	    public final String guestName;
    11	    public final String guestEmail;
    12	    public final String guestCpf;
    13	    public final LocalDate checkIn;
