    10	import java.util.ArrayList;
    11	import java.util.List;
    12	
    13	public class ReservationService {
    14	    /** Booking data already checked for format by the API layer. */
    15	    public record NewReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
    16	                                 LocalDate checkIn, LocalDate checkOut, int guests, String ratePlan,
    17	                                 String companyCode) {}
    18	
    19	    private final List<Room> rooms = List.of(
    20	            new Room(101, RoomType.STANDARD), new Room(102, RoomType.STANDARD),
    21	            new Room(201, RoomType.DELUXE), new Room(202, RoomType.DELUXE),
    22	            new Room(301, RoomType.SUITE));
    23	    private final List<Reservation> reservations = new ArrayList<>();
    24	    private final Outbox outbox;
    25	    private final Clock clock;
    26	
    27	    public ReservationService(Outbox outbox, Clock clock) {
    28	        this.outbox = outbox;
    29	        this.clock = clock;
    30	    }
    31	
    32	    public List<Room> rooms() {
    33	        return rooms;
    34	    }
    35	
    36	    public synchronized Reservation create(NewReservation req) {
    37	        Room room = rooms.stream().filter(r -> r.number() == req.roomNumber()).findFirst()
    38	                .orElseThrow(() -> new ApiException(404, "ROOM_NOT_FOUND", "Quarto " + req.roomNumber() + " não existe."));
    39	        if (req.guests() > room.capacity()) {
    40	            throw new ApiException(422, "CAPACITY_EXCEEDED",
    41	                    "O quarto " + room.number() + " comporta até " + room.capacity() + " pessoas.");
    42	        }
    43	        RatePlan plan = RatePlans.find(req.ratePlan())
    44	                .orElseThrow(() -> ApiException.invalid("Plano de tarifa desconhecido: " + req.ratePlan()));
    45	        Stay stay = new Stay(room.type(), req.checkIn(), req.checkOut(), req.companyCode(), LocalDate.now(clock));
    46	        Pricing pricing = plan.price(stay);
    47	        boolean taken = reservations.stream().anyMatch(r -> r.room.equals(room)
    48	                && r.status != ReservationStatus.CANCELLED && r.overlaps(req.checkIn(), req.checkOut()));
    49	        if (taken) {
    50	            throw new ApiException(409, "ROOM_UNAVAILABLE", "O quarto " + room.number() + " já está reservado nesse período.");
    51	        }
    52	        Reservation reservation = new Reservation(reservations.size() + 1, room, req.guestName(), req.guestEmail(),
    53	                req.guestCpf(), req.checkIn(), req.checkOut(), req.guests(), plan, stay.nights(),
    54	                pricing.subtotal(), pricing.discount(), pricing.total());
    55	        reservations.add(reservation);
    56	        return reservation;
    57	    }
    58	
    59	    public synchronized Reservation get(String id) {
    60	        try {
    61	            int index = Integer.parseInt(id);
    62	            if (index >= 1 && index <= reservations.size()) {
    63	                return reservations.get(index - 1);
    64	            }
    65	        } catch (NumberFormatException ignored) {
    66	            // falls through to not found
    67	        }
    68	        throw new ApiException(404, "RESERVATION_NOT_FOUND", "Reserva " + id + " não existe.");
    69	    }
    70	
    71	    public synchronized Reservation confirm(String id) {
    72	        Reservation r = get(id);
    73	        require(r, r.status == ReservationStatus.PENDING, "confirmar");
    74	        r.status = ReservationStatus.CONFIRMED;
    75	        r.amountPaid = r.total;
    76	        Receipt receipt = Receipt.of(r);
    77	        outbox.sendEmail(r.guestEmail, "Reserva confirmada - Pousada Maré Alta",
    78	                "Olá, " + r.guestName + "!\n\n"
    79	                        + "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n"
    80	                        + receipt.text() + "\n\n"
    81	                        + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
    82	                        + "Até breve!");
    83	        return r;
    84	    }
    85	
    86	    public synchronized Reservation checkIn(String id) {
    87	        Reservation r = get(id);
    88	        require(r, r.status == ReservationStatus.CONFIRMED, "fazer check-in de");
    89	        r.status = ReservationStatus.CHECKED_IN;
    90	        return r;
    91	    }
    92	
    93	    public synchronized Receipt checkOut(String id) {
    94	        Reservation r = get(id);
    95	        require(r, r.status == ReservationStatus.CHECKED_IN, "fazer check-out de");
    96	        r.status = ReservationStatus.CHECKED_OUT;
    97	        return Receipt.of(r);
    98	    }
    99	
   100	    public synchronized Reservation cancel(String id) {
   101	        Reservation r = get(id);
   102	        require(r, r.status == ReservationStatus.PENDING || r.status == ReservationStatus.CONFIRMED, "cancelar");
   103	        r.refund = Money.round(r.ratePlan.refund(r.amountPaid));
   104	        r.status = ReservationStatus.CANCELLED;
   105	        return r;
   106	    }
   107	
   108	    public synchronized Receipt document(String id) {
   109	        Reservation r = get(id);
   110	        require(r, r.status.isPaid(), "emitir a segunda via de");
   111	        return Receipt.of(r);
   112	    }
   113	
   114	    public synchronized String occupancyReport(LocalDate night) {
   115	        return Reports.occupancy(night, List.copyOf(reservations), rooms);
   116	    }
   117	
   118	    public synchronized String revenueReport(YearMonth month) {
   119	        return Reports.revenue(month, List.copyOf(reservations));
   120	    }
   121	
   122	    private static void require(Reservation r, boolean allowed, String action) {
   123	        if (!allowed) {
   124	            throw new ApiException(409, "OPERATION_NOT_ALLOWED",
   125	                    "Não é possível " + action + " a reserva " + r.id + " com status " + r.status + ".");
   126	        }
   127	    }
   128	}
