     1	package br.com.mareal.domain;
     2	
     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	import java.time.Month;
     6	
     7	/** Nightly pricing with the high-season surcharge. */
     8	public final class Season {
     9	    private static final BigDecimal HIGH_SEASON_FACTOR = new BigDecimal("1.20");
    10	
    11	    private Season() {}
    12	
    13	    public static boolean isHigh(LocalDate night) {
    14	        Month month = night.getMonth();
    15	        return month == Month.JANUARY || month == Month.FEBRUARY || month == Month.JULY
    16	                || (month == Month.DECEMBER && night.getDayOfMonth() >= 15);
    17	    }
    18	
    19	    public static BigDecimal nightPrice(RoomType type, LocalDate night) {
    20	        return isHigh(night) ? Money.percent(type.nightlyRate, HIGH_SEASON_FACTOR) : type.nightlyRate;
    21	    }
    22	
    23	    /** Sum of the nights in [checkIn, checkOut), each night already rounded. */
    24	    public static BigDecimal sumOfNights(RoomType type, LocalDate checkIn, LocalDate checkOut) {
    25	        BigDecimal sum = Money.ZERO;
    26	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    27	            sum = sum.add(nightPrice(type, night));
    28	        }
    29	        return Money.round(sum);
    30	    }
    31	}
