    13	    public static String occupancy(LocalDate night, List<Reservation> all, List<Room> rooms) {
    14	        List<Reservation> occupying = all.stream()
    15	                .filter(r -> r.status.isPaid() && r.occupies(night))
    16	                .sorted(Comparator.comparingInt((Reservation r) -> r.room.number()).thenComparingInt(r -> r.id))
    17	                .toList();
    18	        StringBuilder sb = new StringBuilder("room,type,reservation,check_in,check_out\n");
    19	        for (Reservation r : occupying) {
    20	            sb.append(r.room.number()).append(',').append(r.room.type()).append(',').append(r.id).append(',')
    21	                    .append(r.checkIn).append(',').append(r.checkOut).append('\n');
    22	        }
    23	        long occupiedRooms = occupying.stream().map(r -> r.room.number()).distinct().count();
    24	        sb.append("total,").append(occupiedRooms).append('/').append(rooms.size()).append('\n');
    25	        return sb.toString();
    26	    }
    27	
    28	    public static String revenue(YearMonth month, List<Reservation> all) {
    29	        List<Reservation> kept = all.stream()
    30	                .filter(r -> YearMonth.from(r.checkIn).equals(month) && r.netAmount().signum() > 0)
    31	                .sorted(Comparator.comparing((Reservation r) -> r.checkIn).thenComparingInt(r -> r.id))
    32	                .toList();
    33	        StringBuilder sb = new StringBuilder("reservation,room,check_in,check_out,status,amount\n");
    34	        BigDecimal sum = Money.ZERO;
    35	        for (Reservation r : kept) {
    36	            sb.append(r.id).append(',').append(r.room.number()).append(',').append(r.checkIn).append(',')
    37	                    .append(r.checkOut).append(',').append(r.status).append(',').append(r.netAmount()).append('\n');
    38	            sum = sum.add(r.netAmount());
    39	        }
    40	        sb.append("total,").append(Money.round(sum)).append('\n');
    41	        return sb.toString();
    42	    }
    43	}
